<?php
 namespace Pterodactyl\Http\Controllers\Dezerx; use Throwable; use Illuminate\Http\Request; use Illuminate\Http\Response; use Illuminate\Http\JsonResponse; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\RateLimiter; use Pterodactyl\Models\Dezerx\DiscordBot; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\DiscordBot\Deferral; use Pterodactyl\Services\Dezerx\DiscordBot\Signature; use Pterodactyl\Services\Dezerx\DiscordBot\Dispatcher; use Pterodactyl\Services\Dezerx\DiscordBot\Interaction; use Pterodactyl\Services\Dezerx\DiscordBot\Views\Cards; class DiscordInteractionController extends Controller { private const MAX_BODY = 262144; private const USER_LIMIT = 12; private const USER_WINDOW = 30; private const SUGGEST_LIMIT = 40; private const SUGGEST_WINDOW = 10; private const PERSONAL_LIMIT = 40; private const PERSONAL_WINDOW = 60; public function __construct(private Dispatcher $dispatcher) { } public function __invoke(Request $request, string $bot): JsonResponse|Response { if ((int) $request->header('Content-Length', '0') > self::MAX_BODY) { return response('Request too large.', 413); } $model = DiscordBot::query()->where('uuid', $bot)->first(); if ($model === null) { return response('Unknown bot.', 404); } $body = (string) $request->getContent(); if (strlen($body) > self::MAX_BODY) { return response('Request too large.', 413); } $valid = Signature::verify( (string) $model->public_key, (string) $request->header('X-Signature-Ed25519', ''), (string) $request->header('X-Signature-Timestamp', ''), $body, ); if (!$valid) { return response('Invalid request signature.', 401); } $payload = json_decode($body, true); if (!is_array($payload)) { return response('Malformed body.', 400); } if ((int) ($payload['type'] ?? 0) === Interaction::PING) { return new JsonResponse(['type' => 1]); } if (!$this->firstSighting($payload)) { return response('Interaction already handled.', 409); } $interaction = new Interaction($payload); $limited = $this->limited($model, $interaction); if ($limited !== null) { return new JsonResponse($limited); } try { [$reply, $later] = $this->dispatcher->handle($model, $payload); } catch (Throwable $exception) { Log::error('discord bot: handling an interaction failed', [ 'bot' => $model->uuid, 'error' => $exception->getMessage(), 'at' => $exception->getFile() . ':' . $exception->getLine(), ]); return new JsonResponse(Dispatcher::reply(Cards::error('Something went wrong on the panel. The error has been logged for the administrator.'))); } if ($later !== null) { Deferral::schedule($later); } return new JsonResponse($reply, 200, [], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); } private function firstSighting(array $payload): bool { $id = (string) ($payload['id'] ?? ''); if ($id === '' || !ctype_digit($id)) { return false; } try { return Cache::add('dzb:ix:' . $id, 1, Signature::WINDOW * 2); } catch (Throwable) { return true; } } private function limited(DiscordBot $bot, Interaction $interaction): ?array { $user = $interaction->userId(); $suggest = $interaction->type() === Interaction::AUTOCOMPLETE; $buckets = $suggest ? [['dzb:rl:suggest:' . $user, self::SUGGEST_LIMIT, self::SUGGEST_WINDOW]] : [['dzb:rl:user:' . $user, self::USER_LIMIT, self::USER_WINDOW]]; if (!$suggest && !$bot->isGlobal()) { $buckets[] = ['dzb:rl:bot:' . $bot->id, self::PERSONAL_LIMIT, self::PERSONAL_WINDOW]; } try { foreach ($buckets as [$key, $limit, $window]) { if (RateLimiter::tooManyAttempts($key, $limit)) { $wait = max(1, RateLimiter::availableIn($key)); return $suggest ? ['type' => 8, 'data' => ['choices' => []]] : Dispatcher::reply(Cards::slowDown($wait, str_starts_with($key, 'dzb:rl:bot:'))); } } foreach ($buckets as [$key, , $window]) { RateLimiter::hit($key, $window); } } catch (Throwable) { } return null; } } 